// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address caller, uint256 newThreshold) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());
        newThreshold = bound(newThreshold, 0, 10000);

        uint256 thresholdBefore = c.slippageThresholdGmxBps();

        vm.prank(caller);
        bool ok = true;
        try c.setThresholds(newThreshold) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 thresholdAfter = c.slippageThresholdGmxBps();

        assertTrue(!ok || thresholdAfter == thresholdBefore);
    }
}
